import csv
import io


def parse_fare_table(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    fares = {}
    reader = csv.reader(io.StringIO(text), delimiter=";")
    for row in reader:
        if not row or all(not field.strip() for field in row):
            continue
        if len(row) != 2:
            raise ValueError("each row must contain two fields")
        route = row[0].strip()
        raw_fare = row[1].strip()
        if not route or not raw_fare:
            raise ValueError("fields must not be empty")
        try:
            fare = int(raw_fare, 10)
        except ValueError as error:
            raise ValueError("fare must be an integer") from error
        if fare < 0:
            raise ValueError("fare must be non-negative")
        if route not in fares:
            fares[route] = fare
    return fares


def find_fare(fares, route):
    if not isinstance(fares, dict):
        raise TypeError("fares must be a dictionary")
    if not isinstance(route, str):
        raise TypeError("route must be a string")
    for key, value in fares.items():
        if not isinstance(key, str) or isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("fare entries have invalid types")
        if value < 0:
            raise ValueError("fare values must be non-negative")
    return fares.get(route)

